import json
from pathlib import Path
def load(n):return json.loads(Path('research/modalities/'+n+'.json').read_text(encoding='utf-8'))
def out(k,v):print(k,json.dumps(v,ensure_ascii=True,indent=2))
r=load('expression-validation-readiness')
for c,v in r['cohorts'].items():
 out(c,{k:v for k,v in v.items() if k not in ['samples','source_facts']})
p=load('emc-expression-panels-inputs')
for c,v in p['targets'].items():
 out(c+'keys',list(v));out(c+'platform',v.get('platform'));out(c+'sample0',v['samples'][0]);out(c+'other', {k:v for k,v in v.items() if k not in ['samples','genes','background_reads_block']})
'@ | & 'C:\\Users\\mcrae\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\python\\python.exe' -"

